package com.autoops.machine.controller;import com.autoops.machine.entity.Machine;import com.autoops.machine.repository.MachineRepository;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/machines")public class MachineController{private final MachineRepository repo;public MachineController(MachineRepository r){repo=r;}@GetMapping public List<Machine> list(){return repo.findByDeletedAtIsNull();}@GetMapping("/{id}")public Machine get(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PostMapping public Machine create(@RequestBody Machine m){return repo.save(m);}}
